#include<iostream>
using namespace std;
class Timer{
private:
int sec;
public:
Timer(){
sec=0;
}
Timer operator++(){//注意返回值不是引用
sec++;
return *this;
}
void show(){
cout<<sec<<endl;
}
};
int main(){
Timer t;
++(++(++t));//连续调用三次前置++
t.show();
return 0;
